import{_ as a,o as t,c as o,ae as r}from"./chunks/framework.vXWZTEWX.js";const g=JSON.parse('{"title":"ADR 025: Manual Native Redirect for Google Auth 🚀","description":"","frontmatter":{},"headers":[],"relativePath":"adr/025-manual-native-redirect.md","filePath":"adr/025-manual-native-redirect.md"}'),i={name:"adr/025-manual-native-redirect.md"};function n(s,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-025-manual-native-redirect-for-google-auth-🚀" tabindex="-1">ADR 025: Manual Native Redirect for Google Auth 🚀 <a class="header-anchor" href="#adr-025-manual-native-redirect-for-google-auth-🚀" aria-label="Permalink to &quot;ADR 025: Manual Native Redirect for Google Auth 🚀&quot;">​</a></h1><p>Date: 2026-03-04</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The previous Google Auth implementation using the <code>@react-oauth/google</code> library functioned correctly in local environments but failed in the Render production environment (<code>.onrender.com</code>). This failure was due to strict <strong>Cross-Origin-Opener-Policy (COOP)</strong> and <strong>Cross-Origin-Embedder-Policy (COEP)</strong> restrictions.</p><p>On shared domains like <code>.onrender.com</code>, libraries that use nested iframes or popups for authentication often trigger COOP communication blocks, leading to the error <code>Cross-Origin-Opener-Policy policy would block the window.closed call</code>. Standard library-based &quot;Redirect UX&quot; modes also failed because they still relied on service workers or background communicators that were blocked by Render&#39;s infrastructure-level headers.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have decided to pivot to a <strong>Manual Native Redirect</strong> strategy for Google Authentication.</p><h3 id="_1-library-removal" tabindex="-1">1. Library Removal <a class="header-anchor" href="#_1-library-removal" aria-label="Permalink to &quot;1. Library Removal&quot;">​</a></h3><p>We removed the <code>@react-oauth/google</code> dependency from the frontend. This reduces bundle size and eliminates invisible library logic that might interfere with URL hashes or cross-origin headers.</p><h3 id="_2-manual-oauth-navigation" tabindex="-1">2. Manual OAuth Navigation <a class="header-anchor" href="#_2-manual-oauth-navigation" aria-label="Permalink to &quot;2. Manual OAuth Navigation&quot;">​</a></h3><p>Instead of using a library hook, we manually construct the Google OAuth 2.0 URL (Implicit Flow) and perform a full-page navigation using <code>window.location.href</code>. This avoids the &quot;Opener&quot; relationship entirely, as the user is navigating away from the app and being redirected back naturally.</p><h3 id="_3-global-hash-capture" tabindex="-1">3. Global Hash Capture <a class="header-anchor" href="#_3-global-hash-capture" aria-label="Permalink to &quot;3. Global Hash Capture&quot;">​</a></h3><p>Because Google redirects the user back to the application root (<code>/</code>), and the user might be landing on the Home page rather than the Login page, we moved the token-detection logic to the <strong>global <code>AuthContext</code></strong>.</p><ul><li>The <code>AuthContext</code> now checks <code>window.location.hash</code> upon initialization.</li><li>If a Google <code>access_token</code> is found, it immediately triggers the backend login and redirects the user to the <code>/dashboard</code>.</li></ul><h3 id="_4-csp-move-to-meta-tag" tabindex="-1">4. CSP Move to Meta Tag <a class="header-anchor" href="#_4-csp-move-to-meta-tag" aria-label="Permalink to &quot;4. CSP Move to Meta Tag&quot;">​</a></h3><p>Content Security Policy (CSP) headers in <code>render.yaml</code> were reaching character limits and causing browser parsing errors (blocking Google Fonts). We moved the primary CSP to a <strong><code>&lt;meta&gt;</code> tag in <code>index.html</code></strong> for more reliable delivery and easier maintenance of complex resource whitelists.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Production Reliability</strong>: Google Auth now works perfectly on the Render free tier and shared subdomains.</li><li><strong>Zero Dependencies</strong>: Reduced reliance on external identity libraries that may have opaque security configurations.</li><li><strong>Improved Performance</strong>: Moving CSP to the meta tag resolved intermittent font-blocking issues.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Manual Maintenance</strong>: Any changes to Google&#39;s OAuth scopes or client IDs must be updated in our manual URL constructor.</li><li><strong>Security Posture</strong>: We use <code>unsafe-none</code> for COOP/COEP headers to maximize compatibility with the redirect flow, though the app remains secured via HttpOnly cookies and strict CSP.</li></ul><h2 id="alternatives-considered" tabindex="-1">alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;alternatives Considered&quot;">​</a></h2><h3 id="using-a-custom-domain" tabindex="-1">Using a Custom Domain <a class="header-anchor" href="#using-a-custom-domain" aria-label="Permalink to &quot;Using a Custom Domain&quot;">​</a></h3><ul><li><strong>Pros</strong>: Would allow standard library-based popups to work.</li><li><strong>Cons</strong>: Adds cost and complexity that the user explicitly wants to avoid for this prototype.</li></ul><h3 id="redirect-mode-library-based" tabindex="-1">Redirect Mode (Library-Based) <a class="header-anchor" href="#redirect-mode-library-based" aria-label="Permalink to &quot;Redirect Mode (Library-Based)&quot;">​</a></h3><ul><li><strong>Pros</strong>: Handles token refreshing and token storage.</li><li><strong>Cons</strong>: Still failed on Render due to library-specific redirect handlers being blocked by the environment&#39;s security posture.</li></ul>',28)])])}const m=a(i,[["render",n]]);export{g as __pageData,m as default};
